mapper.sql:
SELECT c.id, c.content, c.likes, c.created_at, c.reply_count, u.user_id AS user_id, u.user_name AS user_name, u.avatar AS avatar, ir.image_id AS image_id, ir.sort AS image_sort, ir.create_time AS image_create_time, IF(cl.comment_id IS NOT NULL, 1, 0) AS is_liked FROM comments c LEFT JOIN sys_user u ON c.user_id = u.user_id LEFT JOIN images_record ir ON c.id = ir.recipe_id AND ir.table_name = 'comment' LEFT JOIN comment_likes cl ON c.id = cl.comment_id AND cl.user_id = #{currentUserId}
AND c.resource_type = #{query.resourceType}
AND c.resource_id = #{query.resourceId}
AND c.status = 'visible' AND (c.parent_id IS NULL OR c.parent_id = '')
ORDER BY
c.likes DESC, c.created_at DESC c.created_at DESC
LIMIT #{query.pageSize} OFFSET #{offset}

mapper.select:
SELECT COUNT(*)
FROM comments c


        AND c.resource_type = #{resourceType}


        AND c.resource_id = #{resourceId}

    AND c.status = 'visible'
    AND (c.parent_id IS NULL OR c.parent_id = '')

mapper.update:
UPDATE comments
SET reply_count = reply_count + 1
WHERE id = #{id}

UPDATE comments
SET status = 'deleted'
WHERE id = #{id}

UPDATE comments
SET likes = likes + #{increment}
WHERE id = #{id}

mapper.select:
SELECT c.id, c.content, c.created_at AS createTime, c.resource_type AS sourceType, c.resource_id AS sourceId, CASE WHEN c.resource_type = 'recipe' THEN (SELECT title FROM recipes WHERE id = c.resource_id) WHEN c.resource_type = 'forum_question' THEN (SELECT title FROM forum_questions WHERE id = c.resource_id) WHEN c.resource_type = 'forum_share' THEN (SELECT title FROM forum_shares WHERE id = c.resource_id) WHEN c.resource_type = 'forum_activity' THEN (SELECT title FROM forum_activities WHERE id = c.resource_id) ELSE '未知来源' END AS sourceTitle FROM comments c WHERE c.id IN
#{id}
ORDER BY c.created_at DESC
